import{c as a,Q as t,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Beyond tokens: a unified framework for latent communication in LLM-based multi-agent systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.05711","title":"Beyond tokens: a unified framework for latent communication in LLM-based multi-agent systems","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2606.05711,"authors":["Yingzhuo Liu"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2606.05711v1","pdf_path":"pdfs/2606.05711.pdf","published_date":"2026-06-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-04-latent-communication-multi-agent-unified-framework-2606-05711.md","filePath":"research/papers/2026-06-04-latent-communication-multi-agent-unified-framework-2606-05711.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-06-04-latent-communication-multi-agent-unified-framework-2606-05711.md"};function o(s,e,l,c,d,m){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="beyond-tokens-a-unified-framework-for-latent-communication-in-llm-based-multi-agent-systems" tabindex="-1">Beyond tokens: a unified framework for latent communication in LLM-based multi-agent systems <a class="header-anchor" href="#beyond-tokens-a-unified-framework-for-latent-communication-in-llm-based-multi-agent-systems" aria-label="Permalink to &quot;Beyond tokens: a unified framework for latent communication in LLM-based multi-agent systems&quot;">​</a></h1><p><strong>Authors</strong>: Yingzhuo Liu <strong>Published</strong>: June 4, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.05711" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.05711</a> · <a href="https://arxiv.org/html/2606.05711v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.05711 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.05711" target="_blank" rel="noreferrer">research/papers/pdfs/2606.05711.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Multi-agent systems built on large language models (LLMs) have become a prevailing paradigm for tackling complex reasoning, planning, and tool-use tasks. The dominant communication protocol in such systems is natural language: agents exchange messages token-by-token, verbalising their internal reasoning so that peers can read, verify, and respond. While convenient and interpretable, this protocol suffers from three structural drawbacks -- high inference cost, irreversible information loss during discretization, and ambiguity/redundancy of natural language. A growing body of work therefore explores an alternative protocol -- latent communication -- in which agents exchange continuous representations (embeddings, hidden states, or KV-caches) directly, bypassing the bottleneck of text generation. This paper presents a unified framework for organising the rapidly expanding literature on latent communication. We analyse existing methods along three orthogonal axes: (1) WHAT information is communicated (Embeddings, Hidden States, KV-Caches, or other continuous state); (2) WHICH sender-receiver alignment is used (latent-space alignment and layer alignment); and (3) HOW the communicated information is fused into the receiver (concatenation, prepending, mathematical operations, cross-attention, or cache restoration). Under this 3-axis framework, we systematically categorise eighteen representative methods proposed between 2024 and 2026, identify five major design patterns, and surface a set of open challenges -- including cross-architecture alignment, security of latent channels, compression for edge deployment, and the relationship between latent communication and latent chain-of-thought.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>Latent communication（agent 間直接交換 embedding/hidden state/KV-cache，繞過 text 生成瓶頸）文獻的統一框架</li><li>三正交軸分類：WHAT（交換什麼連續表徵）× WHICH（sender-receiver 對齊方式）× HOW（接收端融合方式）</li><li>系統化歸類 2024–2026 間 18 個代表方法，萃取 5 大設計模式</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>綜述性論文；開放挑戰包含跨架構對齊、latent channel 安全性、edge 部署壓縮、與 latent CoT 的關係</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>latent 通道犧牲可解讀性與可稽核性——peer 無法「read, verify, and respond」</li><li>多數方法需白盒模型與共同架構，API-based agent 系統不可用</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>對 workspace 是「反面邊界」參考：core.md 的驗證閘門與展示紀律依賴通訊內容人類可稽核，latent channel 安全性被本篇列為 open challenge，正好說明 workspace 選擇 NL 通訊 + 機械失真閘（<code>.claude/skills/output-compress</code>）而非 latent 壓縮的取捨依據。</li><li>「discretization 不可逆資訊損失」提醒：文字層壓縮的 fidelity 上限存在，whitelist 不變式是在此上限內守住決策相關資訊。</li></ul>',16)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
